pub fn tak(x: i64, y: i64, z: i64) -> i64 {
    if y < x {
        return tak(tak(x - 1, y, z), tak(y - 1, z, x), tak(z - 1, x, y));
    }
    y
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_tak() {
        assert_eq!(tak(6, 4, 2), 3);
        assert_eq!(tak(12, 8, 4), 5);
        assert_eq!(tak(1, 2, 3), 3);
    }
}
